    contenu = {"identification": ["Dénomination", "Exercice", "Date de clôture", "Devise",
                                  "Référentiel", "Pays"], "feuilles": sheets}
    table = sa.table("dsf_models", sa.column("id"), sa.column("pays"), sa.column("nom"),
                     sa.column("version"), sa.column("referentiel"), sa.column("actif"),
                     sa.column("contenu", postgresql.JSONB))
